STYLES = {
  'impulsive': 'Герой сперва тянется к немедленной покупке, затем проверяет последствия.',
  'analytical': 'Герой записывает условия двух вариантов и замечает скрытое различие.',
  'creative': 'Герой придумывает необычный способ достичь цели, но сверяет его стоимость.',
  'cautious': 'Герой сначала замечает риск пропустить важную дату или потерять деньги.',
}


def character_style(character):
    text = character['personality']
    if 'импульсив' in text:
        return 'impulsive'
    if 'творчес' in text or 'эмоциональн' in text:
        return 'creative'
    if 'осторожн' in text:
        return 'cautious'
    return 'analytical'
